    AppState.ui.preferencesTrigger = trigger;
    AppState.ui.guideOpen = false;
    AppState.ui.questModalOpen = true;
    AppState.ui.lastSignature = '';
    render();
    document.querySelector('.iw-modal:not(.iw-modal-hidden) [data-modal-close]')?.focus();
    checkSettingsUpdate();
